<?php
require_once __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.DB_HOST.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec('CREATE DATABASE IF NOT EXISTS `'.DB_NAME.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$pdo->exec('USE `'.DB_NAME.'`');$sql=file_get_contents(__DIR__.'/database.sql');foreach(array_filter(array_map('trim',explode(";",$sql))) as $q)$pdo->exec($q);$check=$pdo->query("SELECT COUNT(*) FROM users WHERE username='admin'")->fetchColumn();if(!$check){$p=$pdo->prepare('INSERT INTO users(nama,username,password,role) VALUES(?,?,?,?)');$p->execute(['Administrator','admin',password_hash('admin123',PASSWORD_DEFAULT),'admin']);}echo '<h2>Instalasi berhasil</h2><p><a href="login.php">Masuk ke aplikasi</a> (admin / admin123)</p>';}catch(Throwable $e){echo 'Gagal: '.htmlspecialchars($e->getMessage());}
